{
  "title": "考试前的抉择",
  "scene": "放学后的教室里，同学们正紧张地准备着明天的大考。角落里，你的朋友小明神情焦虑，似乎遇到了难题。你想起昨天他在图书馆借了一本据说对考试有帮助的参考书。小明旁边是平时与他有些小摩擦的小华，小华正偷偷地往小明的书包里塞着什么东西。走廊外，你们的社团即将开始活动，而你作为负责人，还得准备一些东西。",
  "goal": "顺利帮助小明渡过难关，同时不影响社团活动的正常进行",
  "clue": "小华偷偷往小明书包里塞东西，这个动作和表情暗示他可能在搞破坏，但具体是什么需要玩家自行推理。",
  "choices": [
    {
      "id": "A",
      "text": "直接去帮忙复习",
      "outcome": "你全身心投入到帮助小明复习中，但考试时发现他的参考书被换成了一本与考试无关的书，导致成绩不佳。小明对你失去了信任，社团活动也因此受到了影响。",
      "result": "fail",
      "next": "retry"
    },
    {
      "id": "B",
      "text": "先去社团，再回来",
      "outcome": "你先去处理社团事务，回来后发现小明似乎已经解决了问题，但你感到有些不对劲。考试时，小明的成绩并不理想，他找你诉苦，解释说之前你走后小华偷偷换了参考书。",
      "result": "partial",
      "next": "next_level"
    },
    {
      "id": "C",
      "text": "找个理由让小华离开",
      "outcome": "你敏锐地察觉到小华的异常行为，巧妙地找了个理由让他离开。随后你帮小明检查书包，发现了那本被换掉的参考书，及时恢复了原样。小明顺利通过考试，你们的友情也更加深厚，社团活动也因你的细心准备而圆满成功。",
      "result": "success",
      "next": "next_level"
    }
  ]
}
